   216  // https://android.googlesource.com/platform/dalvik/+/android-4.4.2_r2/libdex/Leb128.cpp
   217
   218  int32_t read_uleb128(
   219      const uint8_t* pStream,
   220      uint32_t *size)
   221  {
   222    const uint8_t* ptr = pStream;
   223
   224    int32_t result = *(ptr++);
   225    *size = *size + 1;
   226
   227    if (result > 0x7f)
   228    {
   229      int cur = *(ptr++);
   230      *size = *size + 1;
   231      result = (result & 0x7f) | ((cur & 0x7f) << 7);
   232
   233      if (cur > 0x7f)
   234      {
   235        cur = *(ptr++);
   236        *size = *size + 1;
   237        result |= (cur & 0x7f) << 14;
   238
   239        if (cur > 0x7f)
   240        {
   241          cur = *(ptr++);
   242          *size = *size + 1;
   243          result |= (cur & 0x7f) << 21;
   244
   245          if (cur > 0x7f)
   246          {
   247            /*
   248             * Note: We don't check to see if cur is out of
   249             * range here, meaning we tolerate garbage in the
   250             * high four-order bits.
   251             */
   252            cur = *(ptr++);
   253            *size = *size + 1;
   254            result |= cur << 28;
   255          }
   256        }
   257      }
   258    }
   259
   260    return result;
   261  }
